    V currentVertex = currentEdge.getVertex1();
    if (currentVertex.equals(currentEdge.getVertex2())) {
        // if the current vertex is the same as the target vertex
        // we have reached the end of the path and can return null
        return null;
    }
    // get the next vertex in the path
    V nextVertex = currentEdge.getVertex2();
    if (nextVertex.equals(currentVertex)) {
        // if the next vertex is the same as the current vertex
        // we have reached the end of the path and can return null
        return null;
    }
    // add the next vertex to the path
    path.addVertex(nextVertex);
    // update the current edge with the next vertex
    currentEdge.setVertex1(nextVertex);
    // return the next vertex
    return nextVertex;
}
