public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }
    int filenameStart = path.lastIndexOf(File.separator);
    int extensionStart = path.lastIndexOf(".");
    if (extensionStart == -1) {
        return path;
    }
    if (filenameStart == -1) {
        return path.substring(0, extensionStart);
    }
    if (filenameStart > extensionStart) {
        return path;
    }
    return path.substring(0, filenameStart) + path.substring(extensionStart + 1);
}

public static char[] toPrimitive(final Character[] array){
    if (array == null) {
        return null;
    } else if (array.length == 0) {
        return new char[0];
    } else {
        final char[] result = new char[array.length];
        for (int i = 0; i < array.length; i++) {
            final Character element = array[i];
            if (element == null) {
                throw new NullPointerException("Array content must not be null");
            } else {
                result[i] = element.charValue();
            }
        }
        return result;
    }
}

String trimLeadingCharacter(String str, char leadingCharacter) {
    int startIndex = 0;
    while (startIndex < str.length() && str.charAt(startIndex) == leadingCharacter) {
        startIndex++;
    }
    return str.substring(startIndex);
}

